#include <cstdint>
#include <format>
#include <iostream>
#include <string>
#include <vector>

struct Pose {
  double x_m = 0;
  double y_m = 0;
  double theta_rad = 0;
};

struct Growth {
  std::int64_t reallocations = 0;
  std::int64_t relocated = 0;  // elements carried over to a new block
};

int main() {
  std::vector<Pose> poses;
  Growth doubling;
  for (int i = 0; i < 1'000'000; ++i) {
    if (poses.size() == poses.capacity()) {  // full, so this push allocates a new block
      ++doubling.reallocations;
      doubling.relocated += std::ssize(poses);
    }
    poses.push_back({});
  }
  std::cout << std::format("{} poses: capacity {}, {} reallocations, {} elements relocated\n", poses.size(),
                           poses.capacity(), doubling.reallocations, doubling.relocated);
  poses.clear();
  std::cout << std::format("after clear: size {}, capacity {}\n", poses.size(), poses.capacity());
  poses.shrink_to_fit();
  std::cout << std::format("after shrink_to_fit: size {}, capacity {}\n", poses.size(), poses.capacity());

  std::vector<Pose> exact;
  Growth one_more;
  for (int i = 0; i < 1000; ++i) {
    const auto before = exact.capacity();
    exact.reserve(exact.size() + 1);  // room for one more, every time
    if (exact.capacity() != before) {
      ++one_more.reallocations;
      one_more.relocated += std::ssize(exact);
    }
    exact.push_back({});
  }
  std::cout << std::format("reserve(size() + 1) before each of 1000 pushes: {} reallocations, {} elements relocated\n",
                           one_more.reallocations, one_more.relocated);

  std::string frame;
  std::string capacities = std::to_string(frame.capacity());
  for (int i = 0; i < 200; ++i) {
    const auto before = frame.capacity();
    frame += 'x';
    if (frame.capacity() != before) capacities += " " + std::to_string(frame.capacity());
  }
  std::cout << "string capacity while appending 200 characters: " << capacities << '\n';
}

#include <cmath>
#include <cstddef>
#include <cstdint>
