#include <span>
#include <string>
#include <string_view>
#include <vector>

struct Point {
  float x_m;
  float y_m;
};

// One allocation: reserve makes room for every point, and push_back never reallocates below capacity.
[[nodiscard]] std::vector<Point> to_points(std::span<const float> ranges_m, float angle_step_rad) {
  std::vector<Point> points;
  points.reserve(ranges_m.size());
  for (const std::ptrdiff_t i : std::views::iota(std::ptrdiff_t{0}, std::ssize(ranges_m))) {
    const float angle = angle_step_rad * static_cast<float>(i);
    points.push_back({.x_m = ranges_m[i] * std::cos(angle), .y_m = ranges_m[i] * std::sin(angle)});
  }
  return points;
}

void show(std::string_view step, const std::vector<int>& v) {
  std::cout << std::format("{:<16} size {}, capacity {}\n", step, v.size(), v.capacity());
}

[[nodiscard]] bool stored_inside(const std::string& s) {
  const auto object = reinterpret_cast<std::uintptr_t>(&s);
  const auto chars = reinterpret_cast<std::uintptr_t>(s.data());
  return chars >= object && chars < object + sizeof(s);
}

int main() {
  const std::vector<float> scan(360, 2.0F);
  const std::vector<Point> points = to_points(scan, 0.0174533F);
  std::cout << std::format("{} points, capacity {}\n", points.size(), points.capacity());

  std::vector<int> v;
  v.resize(5);
  show("resize(5)", v);
  v.push_back(1);
  show("push_back(1)", v);
  v.reserve(4);
  show("reserve(4)", v);
  v.shrink_to_fit();
  show("shrink_to_fit()", v);
  v.clear();
  show("clear()", v);
  v.push_back(2);
  show("push_back(2)", v);

  for (const std::string frame : {"base_link", "base_footprint_front_left_wheel"}) {
    std::cout << std::format("{}: {} characters, capacity {}, inside the object: {}\n", frame, frame.size(),
                             frame.capacity(), stored_inside(frame));
  }
}

#include <cstdint>
#include <format>
#include <iostream>
#include <iterator>
#include <map>
#include <optional>

struct Pose {
  double x_m = 0;
  double y_m = 0;
};

using History = std::map<std::int64_t, Pose>;  // stamp in milliseconds -> pose, kept sorted by stamp

// The last pose recorded at or before stamp_ms, if there is one.
[[nodiscard]] std::optional<Pose> pose_at(const History& history, std::int64_t stamp_ms) {
  const auto after = history.upper_bound(stamp_ms);  // first entry later than stamp_ms
  if (after == history.begin()) return std::nullopt;
  return std::prev(after)->second;
}

int main() {
  History history;
  history.emplace(300, Pose{.x_m = 0.3, .y_m = 0.0});
  history.emplace(100, Pose{.x_m = 0.1, .y_m = 0.0});
  history.emplace(200, Pose{.x_m = 0.2, .y_m = 0.1});
  for (const auto& [stamp_ms, pose] : history) std::cout << std::format("{} ms: ({}, {})\n", stamp_ms, pose.x_m, pose.y_m);
  for (const std::int64_t t : {250, 100, 50}) {
    const std::optional<Pose> p = pose_at(history, t);
    std::cout << std::format("pose at {} ms: {}\n", t, p ? std::format("({}, {})", p->x_m, p->y_m) : "none yet");
  }
}

