#include <vector>

struct Tally {
  std::int64_t allocations = 0;
  std::int64_t bytes_held = 0;
};

// Counts every allocation in a Tally the caller owns, then allocates as usual.
template <typename T>
struct Counting {
  using value_type = T;
  Tally* tally;
  explicit Counting(Tally* t) : tally(t) {}
  template <typename U>
  Counting(const Counting<U>& other) : tally(other.tally) {}  // containers allocate nodes and buckets too
  [[nodiscard]] T* allocate(std::size_t n) {
    ++tally->allocations;
    tally->bytes_held += static_cast<std::int64_t>(n * sizeof(T));
    return std::allocator<T>{}.allocate(n);
  }
  void deallocate(T* p, std::size_t n) {
    tally->bytes_held -= static_cast<std::int64_t>(n * sizeof(T));
    std::allocator<T>{}.deallocate(p, n);
  }
  template <typename U>
  bool operator==(const Counting<U>& other) const { return tally == other.tally; }
};

using Entry = std::pair<const int, int>;
constexpr int n = 1000;

void report(std::string_view name, const Tally& t) {
  std::cout << std::format("{:<14} {:>4} allocations, {:>5} bytes held, {:>4.1f} bytes per element\n", name,
                           t.allocations, t.bytes_held, static_cast<double>(t.bytes_held) / n);
}

int main() {
  Tally tree;
  std::map<int, int, std::less<>, Counting<Entry>> by_tree(Counting<Entry>{&tree});
  for (int i = 0; i < n; ++i) by_tree.emplace(i, i);
  report("map", tree);

  Tally hash;
  std::unordered_map<int, int, std::hash<int>, std::equal_to<>, Counting<Entry>> by_hash(
      0, std::hash<int>{}, std::equal_to<>{}, Counting<Entry>{&hash});
  for (int i = 0; i < n; ++i) by_hash.emplace(i, i);
  report("unordered_map", hash);
  std::cout << std::format("{:<14} {} buckets for {} elements\n", "", by_hash.bucket_count(), by_hash.size());

  Tally flat;
  std::vector<std::pair<int, int>, Counting<std::pair<int, int>>> sorted(Counting<std::pair<int, int>>{&flat});
  sorted.reserve(n);
  for (int i = 0; i < n; ++i) sorted.emplace_back(i, i);
  report("sorted vector", flat);
  const auto it = std::ranges::lower_bound(sorted, 640, {}, &std::pair<int, int>::first);
  std::cout << std::format("{:<14} lower_bound finds key {}\n", "", it->first);
}

