#include <vector>

struct SensorInfo {
  std::int32_t rate_hz;
  std::string frame;
};

// std::less<> compares a std::string key with a std::string_view without building a string.
using Registry = std::map<std::string, SensorInfo, std::less<>>;

[[nodiscard]] std::optional<SensorInfo> find_sensor(const Registry& registry, std::string_view name) {
  const auto it = registry.find(name);
  if (it == registry.end()) return std::nullopt;
  return it->second;
}

// Names that start with prefix, in order. Copies, because the caller keeps them.
[[nodiscard]] std::vector<std::string> names_under(const Registry& registry, std::string_view prefix) {
  std::vector<std::string> names;
  for (auto it = registry.lower_bound(prefix); it != registry.end() && it->first.starts_with(prefix); ++it) {
    names.push_back(it->first);
  }
  return names;
}

struct SensorId {
  std::int32_t bus;
  std::int32_t address;
  auto operator<=>(const SensorId&) const = default;  // also gives ==
};

struct SensorIdHash {
  [[nodiscard]] std::size_t operator()(const SensorId& id) const noexcept {
    const std::uint64_t high = static_cast<std::uint32_t>(id.bus);
    const std::uint64_t low = static_cast<std::uint32_t>(id.address);
    return std::hash<std::uint64_t>{}((high << 32) | low);
  }
};

int main() {
  const Registry registry{{"lidar/front", {.rate_hz = 10, .frame = "lidar_front"}},
                          {"camera/rgb", {.rate_hz = 30, .frame = "camera_link"}},
                          {"lidar/rear", {.rate_hz = 10, .frame = "lidar_rear"}},
                          {"imu", {.rate_hz = 200, .frame = "imu_link"}}};
  for (const std::string_view name : {"imu", "sonar"}) {
    const std::optional<SensorInfo> info = find_sensor(registry, name);
    std::cout << std::format("{}: {}\n", name, info ? std::format("{} Hz in {}", info->rate_hz, info->frame) : "not registered");
  }
  std::cout << "under lidar/:";
  for (const std::string& name : names_under(registry, "lidar/")) std::cout << ' ' << name;
  std::cout << "\nstatus report:";
  for (const auto& [name, info] : registry) std::cout << std::format(" {}@{}Hz", name, info.rate_hz);
  std::cout << '\n';

  const std::map<SensorId, std::string> ordered{{{.bus = 1, .address = 0x68}, "imu"}, {{.bus = 0, .address = 0x29}, "tof"}};
  const std::unordered_map<SensorId, std::string, SensorIdHash> hashed{{{.bus = 1, .address = 0x68}, "imu"}};
  std::cout << std::format("first by (bus, address): {}; hashed lookup of 1/0x68: {}\n", ordered.begin()->second,
                           hashed.at({.bus = 1, .address = 0x68}));
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <list>
#include <optional>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <utility>

struct Tile {
  std::int64_t id;
  std::string pixels;  // stands in for the image data
};

// Holds at most `capacity` tiles and evicts the one used least recently.
class TileCache {
 public:
  explicit TileCache(std::ptrdiff_t capacity) : capacity_(capacity) {
    if (capacity < 1) throw std::invalid_argument("a tile cache needs room for at least one tile");
  }

  [[nodiscard]] std::optional<std::string> get(std::int64_t id) {
    const auto it = index_.find(id);
    if (it == index_.end()) return std::nullopt;
    tiles_.splice(tiles_.begin(), tiles_, it->second);  // relinks one node: nothing moves, no iterator dies
    return it->second->pixels;
  }

  void put(std::int64_t id, std::string pixels) {
    if (const auto it = index_.find(id); it != index_.end()) {
      it->second->pixels = std::move(pixels);
      tiles_.splice(tiles_.begin(), tiles_, it->second);
      return;
    }
    if (std::ssize(tiles_) == capacity_) {
      index_.erase(tiles_.back().id);
      tiles_.pop_back();
    }
    tiles_.push_front({.id = id, .pixels = std::move(pixels)});
    index_.emplace(id, tiles_.begin());
  }

 private:
  std::ptrdiff_t capacity_;
  std::list<Tile> tiles_;  // most recently used first
  std::unordered_map<std::int64_t, std::list<Tile>::iterator> index_;
};

int main() {
  TileCache cache(2);
  cache.put(7, "tile 7");
  cache.put(8, "tile 8");
  const auto show = [&cache](std::int64_t id) {
    std::cout << std::format("get({}): {}\n", id, cache.get(id).value_or("miss"));
  };
  show(7);                 // 7 becomes the most recent
  cache.put(9, "tile 9");  // full: evicts 8, the least recent
  show(8);
  show(7);
  show(9);
}
